def transform(grid):
    g = np.array(grid)
    out = g.copy()
    objs = objects(g, bg=0, diagonal=True, multicolour=True)
    template = None
    targets = []
    for o in objs:
        cols = set(int(g[y, x]) for y, x in o["cells"])
        if cols - {2, 4}:
            template = o
        elif 4 in cols and 2 in cols:
            targets.append(o)
    if template is None:
        emit(out, "No template found; output equals input.")
        return out
    tcells = [(y, x, int(g[y, x])) for y, x in template["cells"]]
    core = [(y, x, c) for y, x, c in tcells if c in (2, 4)]
    deco = [(y, x, c) for y, x, c in tcells if c not in (2, 4)]

    def tf(y, x, k):
        # 8 dihedral transforms
        if k & 4:
            y, x = x, y
        if k & 1:
            y = -y
        if k & 2:
            x = -x
        return y, x

    for o in targets:
        tgt = set((y, x, int(g[y, x])) for y, x in o["cells"])
        done = False
        for k in range(8):
            tc = [(*tf(y, x, k), c) for y, x, c in core]
            # align by the 2 marker
            ty2 = [(y, x) for y, x, c in tc if c == 2][0]
            gy2 = [(y, x) for y, x, c in tgt if c == 2][0]
            dy, dx = gy2[0] - ty2[0], gy2[1] - ty2[1]
            moved = set((y + dy, x + dx, c) for y, x, c in tc)
            if moved == tgt:
                for y, x, c in deco:
                    yy, xx = tf(y, x, k)
                    yy += dy; xx += dx
                    if 0 <= yy < out.shape[0] and 0 <= xx < out.shape[1]:
                        out[yy, xx] = c
                done = True
                break
        if done:
            emit(out.copy(), f"Copied the template's decorations onto the shape at {o['box']} using the orientation that matches its 4/2 pattern.")
    emit(out, "All copies of the shape are decorated like the template.")
    return out
